            stage: 'shape',
            goal_cycle: 2,
            iteration: 0,
            attempt: 0,
            next_action: 'prepare-shape-confirmation',
          },
        },
        continuation: { action: 'prepare-shape-confirmation' },
      },
    });

    const archiveContinuation = accepted.data as {
      continuation: {
        action: string;
        commandAlternatives?: Array<{
          name: string;
          expectedAction: string;
          commandArgs: string[];
        }>;
      };
    };
    expect(archiveContinuation.continuation).toMatchObject({
      action: 'archive',
      commandAlternatives: expect.arrayContaining([
        expect.objectContaining({
          name: 'revise-requirements',
          expectedAction: 'revise-requirements',
          commandArgs: expect.arrayContaining([
            '--revise-requirements',
            '--expected-state-version',
            String(archiveStateVersion),
            '--expected-action',
            'revise-requirements',
          ]),
        }),
      ]),
    });

    const staleRevision = json(
      await runNativeCli([
        'next',
        name,
        '--summary',
        'Delayed revision for an obsolete Archive-ready result',
        '--revise-requirements',
        '--expected-state-version',
        String(archiveStateVersion),
        '--expected-action',
        'revise-requirements',
        '--json',
        ...projectArgs(),
      ]),
    );
    expect(staleRevision).toMatchObject({
      exitCode: 65,
      error: {
        message: expect.stringContaining('Native continuation is stale'),
      },
    });
  });

  it('retries an unavailable platform Verifier after its failure budget while preserving candidate and Agent reports', async () => {
    const name = 'retry-unavailable-verifier';
    await prepareBuild(name, ['First behavior works.'], 'zh-CN');
    await runnerStep(name, {
      ...builderHandoff(['A1']),
      checks: [
        {
          name: 'SIMULATED Agent completed check',
          result: 'passed',
          note: 'Agent platform report only; no Comet command',
        },
      ],
    });
    const paths = await nativeProjectPaths(projectRoot, 'docs'),
      built = await readNativePortableChange(paths, name);
    const candidate = built.builder_handoff!.candidate_id,
      reports = structuredClone(built.builder_handoff!.checks);
    await runnerStep(name, { kind: 'dispatch-verifier', checks: [] });
    for (let attempt = 1; attempt <= 3; attempt++) {
      const failed = await runnerStep(name, {
        kind: 'verifier-unavailable',
        summary: 'SIMULATED platform task ended without a usable result.',
      });
      expect(failed.exitCode, JSON.stringify(failed)).toBe(0);
      const state = await readNativePortableChange(paths, name);
      expect(state.builder_handoff!.candidate_id).toBe(candidate);
      expect(state.builder_handoff!.checks).toEqual(reports);
      if (attempt < 3) {
        expect(state.status).toBe('active');
        await runnerStep(name, { kind: 'dispatch-verifier', checks: [] });
      } else expect(state.status).toBe('blocked');
    }
    const blocked = await readNativePortableChange(paths, name);
    const retry = json(
      await runNativeCli([
        'next',
        name,
        '--retry-verifier',
        '--summary',
        'SIMULATED USER explicitly retries the isolated platform review',
        '--expected-state-version',
        String(blocked.state_version),
        '--expected-action',
        'retry-verifier',
        '--json',
        ...projectArgs(),
      ]),
    );
    expect(retry).toMatchObject({
      exitCode: 0,
      data: {
        state: { phase: 'verify', status: 'active', loop: { retry_epoch: 1 } },
        continuation: { action: 'dispatch-verifier' },
      },
    });
    const dispatched = await runnerStep(name, {
      kind: 'dispatch-verifier',
      checks: [],
    });
    expect(dispatched).toMatchObject({
      exitCode: 0,
      data: { verifierDispatch: { candidateId: candidate, attempt: 4 } },
    });
    const after = await readNativePortableChange(paths, name);
    expect(after.builder_handoff!.checks).toEqual(reports);
    expect(after.builder_handoff!.candidate_id).toBe(candidate);
  });

  it('rejects delayed generic Verifier errors and unavailable messages from an older attempt', async () => {
    const name = 'stale-generic-verifier-message';
    await prepareBuild(name);
    await runnerStep(name, builderHandoff(['A1']));
    const firstDispatch = await runnerStep(name, {
      kind: 'dispatch-verifier',
      checks: [],
    });
    const first = {
      ...(firstDispatch.data as any).verifierDispatch,
      ...inputTemplate(firstDispatch, 'verifier-execution-error'),
    };
    const firstError = await runnerStep(name, {
      ...inputTemplate(firstDispatch, 'verifier-execution-error'),
      summary: 'The first Verifier execution ended.',
    });
    expect(firstError).toMatchObject({
      exitCode: 0,
      data: { state: { loop: { stage: 'verify-ready' } } },
    });

    const secondDispatch = await runnerStep(name, {
      kind: 'dispatch-verifier',
      checks: [],
    });
    const second = {
      ...(secondDispatch.data as any).verifierDispatch,
      ...inputTemplate(secondDispatch, 'verifier-execution-error'),
    };
    expect(second.attempt).toBe(first.attempt + 1);
    const before = json(await runNativeCli(['show', name, '--json', ...projectArgs()]));

    for (const kind of ['verifier-execution-error', 'verifier-unavailable'] as const) {
      const delayed = await runnerStep(name, {
        kind,
        summary: 'Delayed message from the previous Verifier.',
        stateVersion: first.stateVersion,
        iteration: first.iteration,
        attempt: first.attempt,
        verifierExecutionRef: first.verifierExecutionRef,
      });
      expect(delayed).toMatchObject({
        exitCode: 65,
        error: {
          message: expect.stringContaining('stale for the current task'),
        },
      });
    }
    const after = json(await runNativeCli(['show', name, '--json', ...projectArgs()]));
    expect(after.data?.state).toMatchObject({
      state_version: (before.data?.state as { state_version: number }).state_version,
      loop: { attempt: second.attempt, execution_failure_count: 1 },
    });
  });

  it('returns friendly localized guidance when Verifier infrastructure repeatedly fails', async () => {
    const name = 'friendly-verifier-recovery';
    await prepareBuild(name, ['The behavior remains safe during verification recovery.'], 'zh-CN');
    await runnerStep(name, builderHandoff(['A1']));

    let failed: JsonEnvelope | null = null;
    for (let attempt = 1; attempt <= 3; attempt += 1) {
      const dispatched = await runnerStep(name, {
        kind: 'dispatch-verifier',
        checks: [],
      });
      expect(dispatched.data?.continuation).toMatchObject({
        action: 'await-verifier',
        userCommunication: {
          required: false,
          message: null,
          suggestedReply: null,
        },
      });
      failed = await runnerStep(name, {
        kind: 'verifier-execution-error',
        summary: `Verifier worker ${attempt} ended without a response.`,
      });
    }

    expect(failed).toMatchObject({
      exitCode: 0,
      data: {
        state: {
          status: 'blocked',
          loop: { attempt: 3, execution_failure_count: 3 },
        },
        continuation: {
          disposition: 'blocked',
          action: 'retry-verifier',
          userCommunication: {
            required: true,
            message:
              '由于独立验收任务连续几次没有正常返回结果，本次验收已暂停。你的代码和已经完成的检查都已安全保留。回复“继续”即可重新尝试，不需要处理文件或进程。',
            suggestedReply: '继续',
            agentInstruction:
              '只向用户转述 message 和 suggestedReply，并等待用户回复。不要展示内部轮次、计数、路径或恢复步骤。',
          },
        },
      },
    });
    const communication = (failed?.data?.continuation as { userCommunication: { message: string } })
      .userCommunication;
    expect(communication.message).not.toMatch(/attempt|requestCheckRounds|Runtime|Verifier/iu);
  });

  it('keeps explicit revise-requirements phase eligibility inside the runtime mutation lock', async () => {
    const name = 'locked-revise-requirements';
    await prepareBuild(name);
    const paths = await nativeProjectPaths(projectRoot, 'docs');

    await expect(
      returnNativePortableChangeToShape({
        paths,
        name,
        reason: 'Attempt explicit Verify/Archive recovery while Build is current',
        allowedPhases: ['verify', 'archive'],
      }),
    ).rejects.toThrow('--revise-requirements is not valid from the current phase');

    const shown = json(await runNativeCli(['show', name, '--json', ...projectArgs()]));
    expect(shown).toMatchObject({
      exitCode: 0,
      data: {
        state: {
          phase: 'build',
          status: 'active',
          loop: { next_action: 'submit-builder-candidate' },
        },
      },
    });
  });

  it('rejects a final result that omits an acceptance ID', async () => {
    const name = 'skill-missing-acceptance';
    await prepareBuild(name, ['First behavior works.', 'Second behavior works.']);
    await runnerStep(name, builderHandoff(['A1', 'A2']));
    await runnerStep(name, { kind: 'dispatch-verifier', checks: [] });

    const missing = await runnerStep(name, finalResponse(1, 1, ['A1']));
    expect(missing).toMatchObject({
      exitCode: 65,
      error: {
        code: 'invalid-data',
        message: expect.stringContaining('missing: A2'),
      },
    });
  });

  it('returns platform-check guidance for Compat without changing the original state', async () => {
    const name = 'check-guidance';
    await prepareBuild(name);
    const paths = await nativeProjectPaths(projectRoot, 'docs'),
      stateFile = nativePortableStateFile(paths, name),
      before = await fs.readFile(stateFile, 'utf8');
    const result = json(await runNativeCli(['check', name, '--json', ...projectArgs()]));
    expect(result).toMatchObject({
      exitCode: 0,
      data: {
        name,
        status: 'platform-execution-required',
        checksExecuted: false,
        next: expect.stringContaining('Agent'),
      },
    });
    expect(await fs.readFile(stateFile, 'utf8')).toBe(before);
    expect((await runNativeCli(['check', '--help'])).exitCode).toBe(0);
  });

  it('returns platform-check guidance without changing the SDK Run or its original task', async () => {
    const name = 'sdk-check';
    const created = json(await runNativeCli(['new', name, '--json', ...projectArgs()]));
    expect(created.exitCode).toBe(0);
    const before = (await inspectNativeSdkRun(projectRoot, name)).run;
    const checked = json(await runNativeCli(['check', name, '--json', ...projectArgs()]));
    expect(checked).toMatchObject({
      exitCode: 0,
      data: {
        name,
        status: 'platform-execution-required',
        checksExecuted: false,
      },
    });
    expect((await inspectNativeSdkRun(projectRoot, name)).run).toEqual(before);
    expect((await runNativeCli(['check', '--help'])).exitCode).toBe(0);
  });

  it('keeps SDK spec sync out of the legacy state mutation path', async () => {
    const created = json(await runNativeCli(['new', 'sdk-sync', '--json', ...projectArgs()]));
    expect(created.exitCode).toBe(0);
    const input = path.join(projectRoot, 'sync-input.json');
    await fs.writeFile(
      input,
      JSON.stringify({
        actor: 'agent',
        reason: 'Reference correction',
        expectedStateVersion: 1,
        affectedAcceptanceIds: ['A1'],
        replacements: [{ from: 'old-ref', to: 'new-ref' }],
      }),
    );
    const synced = json(
      await runNativeCli([
        'spec',
        'sync',
        'sdk-sync',
        'workflow',
        '--input',
        'sync-input.json',
        '--json',
        ...projectArgs(),
      ]),
    );
    expect(synced).toMatchObject({
      exitCode: 64,
      error: { message: expect.stringContaining('SDK') },
    });
    expect(synced.error?.message).toContain('revise-requirements');
    expect((await inspectNativeSdkRun(projectRoot, 'sdk-sync')).state.state_version).toBe(1);
    const help = await runNativeCli(['spec', 'sync', '--help']);
    expect(help.stdout).toContain('Compat-only');
    expect(help.stdout).toContain('revise-requirements');
  });

  it('resolves a semantic Verifier blocker only after the current user decision and forwards the resolution to its next attempt', async () => {
    const name = 'resolve-semantic-blocker',
      acceptance = Array.from({ length: 40 }, (_, i) => 'Behavior ' + (i + 1) + ' works.'),
      ids = acceptance.map((_, i) => 'A' + (i + 1));
    await prepareBuild(name, acceptance);
    await runnerStep(name, {
      ...builderHandoff(ids),
      checks: [
        {
          name: 'SIMULATED Agent baseline',
          result: 'passed',
          note: 'Agent platform report; no managed execution',
        },
      ],
    });
    await runnerStep(name, { kind: 'dispatch-verifier', checks: [] });
    const blocked = await runnerStep(name, {
      kind: 'verifier-response',
      response: {
        kind: 'final-result',
        result: {
          iteration: 1,
          attempt: 1,
          verdict: 'blocked',
          acceptance: ids.map((id) => ({
            id,
            result: 'blocked',
            reason: 'The user must clarify the selected public behavior.',
          })),
          risks: [],
          summary: 'Semantic verification needs a user decision.',
        },
      },
    });
    expect(blocked).toMatchObject({
      exitCode: 0,
      data: {
        state: {
          phase: 'verify',
          status: 'await-user',
          loop: { iteration: 1, attempt: 1, retry_epoch: 0 },
          blockers: [{ resolution_action: 'resolve-verifier-blocker' }],
        },
        continuation: {
          action: 'resolve-verifier-blocker',
          commandArgs: null,
          commandAlternatives: expect.arrayContaining([
            expect.objectContaining({
              name: 'resolve-verifier-blocker',
              requiredInputs: ['summary', 'user-resolution'],
            }),
            expect.objectContaining({ name: 'revise-implementation' }),
            expect.objectContaining({ name: 'revise-requirements' }),
          ]),
        },
      },
    });
    const paths = await nativeProjectPaths(projectRoot, 'docs'),
      state = await readNativePortableChange(paths, name),
      before = await fs.readFile(nativePortableStateFile(paths, name), 'utf8'),
      summary =
        'SIMULATED USER clarified the selected public behavior; keep the existing candidate.';
    const stale = json(
      await runNativeCli([
        'next',
        name,
        '--resolve-verifier-blocker',
        '--summary',
        summary,
        '--expected-state-version',
        String(state.state_version - 1),
        '--expected-action',
        'resolve-verifier-blocker',
        '--json',
        ...projectArgs(),
      ]),
    );
    expect(stale.exitCode).not.toBe(0);
    expect(await fs.readFile(nativePortableStateFile(paths, name), 'utf8')).toBe(before);
    const resolved = json(
      await runNativeCli([
        'next',
        name,
        '--resolve-verifier-blocker',
        '--summary',
        summary,
        '--expected-state-version',
        String(state.state_version),
        '--expected-action',
        'resolve-verifier-blocker',
        '--json',
        ...projectArgs(),
      ]),
    );
    expect(resolved).toMatchObject({
      exitCode: 0,
      data: {
        state: {
          phase: 'verify',
          status: 'active',
          verification_result: 'pending',
          loop: { iteration: 1, attempt: 1, retry_epoch: 1 },
        },
        continuation: { action: 'dispatch-verifier' },
      },
    });
    const resumed = await readNativePortableChange(paths, name);
    expect(resumed.builder_handoff).toEqual(state.builder_handoff);
    expect(resumed.history.at(-1)!.summary.text).toBe(summary);
    const dispatch = await runnerStep(name, {
      kind: 'dispatch-verifier',
      checks: [],
    });
    expect(dispatch).toMatchObject({
      exitCode: 0,
      data: {
        verifierDispatch: {
          candidateId: state.builder_handoff!.candidate_id,
          iteration: 1,
          attempt: 2,
          recoveryContext: { text: summary, truncated: false },
        },
      },
    });
    expect((dispatch.data!.verifierDispatch as any).acceptance.map((a: any) => a.id)).toEqual(ids);
    const pass = await runnerStep(name, finalResponse(1, 2, ids));
    expect(pass).toMatchObject({
      exitCode: 0,
      data: {
        state: {
          phase: 'verify',
          status: 'await-user',
          verification_result: 'pass',
          loop: { attempt: 2 },
        },
      },
    });
  });
});

